<?php
defined( 'ABSPATH' ) || exit;

/** Site data generated by wp_data.py (single source of truth: content.py). */
function rrm_data( $key = null ) {
	static $data = null;
	if ( null === $data ) {
		$file = RRM_WP . '/data/site.json';
		$data = file_exists( $file ) ? json_decode( (string) file_get_contents( $file ), true ) : array();
		if ( ! is_array( $data ) ) {
			$data = array();
		}
	}
	if ( null === $key ) {
		return $data;
	}
	return isset( $data[ $key ] ) ? $data[ $key ] : null;
}

function rrm_service( $key ) {
	$s = rrm_data( 'services' );
	return isset( $s[ $key ] ) ? $s[ $key ] : null;
}

function rrm_assets_url( $path = '' ) {
	return plugins_url( 'wordpress/theme/rankright/assets/' . ltrim( $path, '/' ), RRM_FILE );
}

/** Replace build-time placeholders with live URLs (keeps content portable between domains). */
function rrm_placeholders( $html ) {
	return strtr(
		(string) $html,
		array(
			'{{ASSETS}}' => untrailingslashit( rrm_assets_url() ),
			'{{HOME}}'   => untrailingslashit( home_url() ),
		)
	);
}

function rrm_icon( $name, $class = '' ) {
	$c = $class ? ' class="' . esc_attr( $class ) . '"' : '';
	return '<svg' . $c . ' aria-hidden="true" focusable="false"><use href="' . esc_url( rrm_assets_url( 'img/icons.svg' ) ) . '#' . esc_attr( $name ) . '"></use></svg>';
}

function rrm_money( $price ) {
	if ( '' === $price || null === $price ) {
		return __( 'Custom', 'rankright' );
	}
	$p = (float) $price;
	$s = ( floor( $p ) == $p ) ? number_format( $p, 0 ) : number_format( $p, 2 );
	return get_woocommerce_currency_symbol() . $s;
}

/** Packages (WooCommerce products) for a service, in display order. */
function rrm_packages( $service_key ) {
	if ( ! function_exists( 'wc_get_products' ) ) {
		return array();
	}
	return wc_get_products(
		array(
			'status'     => 'publish',
			'limit'      => 20,
			'orderby'    => 'menu_order',
			'order'      => 'ASC',
			'meta_key'   => '_rrm_service',
			'meta_value' => $service_key,
		)
	);
}

function rrm_pkg_meta( $product, $key, $default = '' ) {
	$v = $product->get_meta( '_rrm_' . $key, true );
	return ( '' === $v || null === $v ) ? $default : $v;
}

function rrm_pkg_features( $product ) {
	$f = json_decode( (string) $product->get_meta( '_rrm_features', true ), true );
	return is_array( $f ) ? $f : array();
}

function rrm_reading_time( $post_id ) {
	$words = str_word_count( wp_strip_all_tags( get_post_field( 'post_content', $post_id ) ) );
	return max( 1, (int) ceil( $words / 225 ) );
}
